CREATE VIEW vw_game_preference_margin AS SELECT GameKey, GameID, GameTitle, avg_s_similarity, max_s_similarity, avg_a_similarity, max_a_similarity, avg_lower_similarity, max_lower_similarity, round(((avg_s_similarity + avg_a_similarity) / 2.0), 2) AS avg_favorite_similarity, round(((max_s_similarity + max_a_similarity) / 2.0), 2) AS max_favorite_similarity, round((((avg_s_similarity + avg_a_similarity) / 2.0) - avg_lower_similarity), 2) AS preference_margin FROM vw_game_preference_similarity;
